window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b3eda896b04ddb8"]={"versions": [{"id": "FIG-9b3eda896b04ddb8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm nach der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung eines einzelnen Arbeitsschritts im Build- und Generierungsprozess von Basissoftware (BSW). Das Diagramm beschreibt die Übersetzung generierter BSW-Konfigurations-Quelldateien in binären Objektcode innerhalb der klassischen AUTOSAR-Entwicklungskette.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität (Task):</strong> <code>Compile BSW Configuration Data</code></li>\n<li><strong>Eingangs-Artefakte (<code>«input»</code>):</strong></li>\n<li><code>Basic Software Module Core Header</code> (Kardinalität: 1)</li>\n<li><code>BSW Module Configuration Data Source Code</code> (Kardinalität: 1)</li>\n<li><code>BSW Module Configuration Header File</code> (Kardinalität: 1)</li>\n<li><strong>Ausgangs-Artefakt (<code>«output»</code>):</strong></li>\n<li><code>BSW Module Configuration Data Object Code</code> (Kardinalität: 1)</li>\n<li><strong>Werkzeug (<code>«used tool»</code>):</strong></li>\n<li><code>Compiler</code> (symbolisiert durch Hammer-Piktogramm)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der Eingangsdateien: Der statische BSW-Kern-Header (<code>Basic Software Module Core Header</code>), die generierte Quellcodedatei (<code>BSW Module Configuration Data Source Code</code>) sowie die generierte Konfigurations-Headerdatei (<code>BSW Module Configuration Header File</code>) werden der Build-Aktivität zugeführt.</li>\n<li>Ausführung: Der <code>Compiler</code> übersetzt den Konfigurationsquellcode unter Einbindung der referenzierten Header-Definitionen.</li>\n<li>Ergebnis: Als Artefakt entsteht die kompilierte Objektcodedatei <code>BSW Module Configuration Data Object Code</code> für das jeweilige BSW-Modul.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Schritt trennt die Kompilierung rein konfigurativer Daten (z. B. Post-Build- oder link-time-fähige Datenstrukturen) von der Kompilierung des statischen Modulcodes.</li>\n<li>Alle drei Eingangsartefakte sind mit einer Kardinalität von exakt 1 spezifiziert, was die Konsistenz der Modulkonfigurations-Schnittstellen voraussetzt.</li>\n<li>Das Ausgangsartefakt geht typischerweise in nachfolgende Link- oder Integrationsschritte auf Steuergeräte-Ebene ein.</li>\n</ul>"}, {"id": "FIG-e21fa4f2c63f7853", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm nach der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung eines einzelnen Arbeitsschritts im Build- und Generierungsprozess von Basissoftware (BSW). Das Diagramm beschreibt die Übersetzung generierter BSW-Konfigurations-Quelldateien in binären Objektcode innerhalb der klassischen AUTOSAR-Entwicklungskette.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität (Task):</strong> <code>Compile BSW Configuration Data</code></li>\n<li><strong>Eingangs-Artefakte (<code>«input»</code>):</strong></li>\n<li><code>Basic Software Module Core Header</code> (Kardinalität: 1)</li>\n<li><code>BSW Module Configuration Data Source Code</code> (Kardinalität: 1)</li>\n<li><code>BSW Module Configuration Header File</code> (Kardinalität: 1)</li>\n<li><strong>Ausgangs-Artefakt (<code>«output»</code>):</strong></li>\n<li><code>BSW Module Configuration Data Object Code</code> (Kardinalität: 1)</li>\n<li><strong>Werkzeug (<code>«used tool»</code>):</strong></li>\n<li><code>Compiler</code> (symbolisiert durch Hammer-Piktogramm)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der Eingangsdateien: Der statische BSW-Kern-Header (<code>Basic Software Module Core Header</code>), die generierte Quellcodedatei (<code>BSW Module Configuration Data Source Code</code>) sowie die generierte Konfigurations-Headerdatei (<code>BSW Module Configuration Header File</code>) werden der Build-Aktivität zugeführt.</li>\n<li>Ausführung: Der <code>Compiler</code> übersetzt den Konfigurationsquellcode unter Einbindung der referenzierten Header-Definitionen.</li>\n<li>Ergebnis: Als Artefakt entsteht die kompilierte Objektcodedatei <code>BSW Module Configuration Data Object Code</code> für das jeweilige BSW-Modul.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Schritt trennt die Kompilierung rein konfigurativer Daten (z. B. Post-Build- oder link-time-fähige Datenstrukturen) von der Kompilierung des statischen Modulcodes.</li>\n<li>Alle drei Eingangsartefakte sind mit einer Kardinalität von exakt 1 spezifiziert, was die Konsistenz der Modulkonfigurations-Schnittstellen voraussetzt.</li>\n<li>Das Ausgangsartefakt geht typischerweise in nachfolgende Link- oder Integrationsschritte auf Steuergeräte-Ebene ein.</li>\n</ul>"}], "trans": [{"from": "FIG-9b3eda896b04ddb8", "to": "FIG-e21fa4f2c63f7853", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
